+                                Cell::from(format_tokens(s.tokens_used)),
+                                Cell::from(relative_time(s.updated_at)),
+                            ]).style(row_style)
+                        }).collect();
+
+                        let table = Table::new(rows, [
+                            Constraint::Length(2),
+                            Constraint::Fill(1),
+                            Constraint::Length(12),
+                            Constraint::Length(8),
+                            Constraint::Length(13),
+                        ])
+                        .header(header)
+                        .row_highlight_style(Style::default().fg(Color::Indexed(255)).bg(Color::Indexed(237)))
+                        .column_spacing(2);
+
+                        f.render_stateful_widget(table, chunks[1], &mut session_state);
+                    }
+
+                    f.render_widget(session_action_bar(active_action), chunks[2]);
+                }
+            }
+        })?;
+
+        if !event::poll(std::time::Duration::from_millis(50))? { continue; }
+        let Event::Key(key) = event::read()? else { continue; };
+        if key.kind != KeyEventKind::Press { continue; }
+
+        // Snapshot view before any mutation to avoid borrow conflicts.
+        let current_view = view;
+        match (current_view, key.code) {
+            (View::Repos, KeyCode::Up | KeyCode::Char('k')) => {
