+            }
+            (View::Repos, KeyCode::Down | KeyCode::Char('j')) => {
+                let n = repos.len();
+                let i = repo_state.selected().unwrap_or(0);
+                repo_state.select(Some((i + 1) % n));
+            }
+            (View::Repos, KeyCode::Enter) => {
+                let idx = repo_state.selected().unwrap_or(0);
+                view = View::Sessions { repo_idx: idx };
+                session_state.select(Some(0));
+            }
+            (View::Repos, KeyCode::Esc | KeyCode::Char('q')) => break,
+
+            (View::Sessions { repo_idx }, KeyCode::Up | KeyCode::Char('k')) => {
+                let n = sessions_by_repo[repo_idx].len();
+                if n > 0 {
+                    let i = session_state.selected().unwrap_or(0);
+                    session_state.select(Some(if i == 0 { n - 1 } else { i - 1 }));
+                }
+            }
+            (View::Sessions { repo_idx }, KeyCode::Down | KeyCode::Char('j')) => {
+                let n = sessions_by_repo[repo_idx].len();
+                if n > 0 {
+                    let i = session_state.selected().unwrap_or(0);
+                    session_state.select(Some((i + 1) % n));
+                }
+            }
+            (View::Sessions { .. }, KeyCode::Tab) => {
+                active_action = (active_action + 1) % 2;
+            }
+            (View::Sessions { repo_idx }, KeyCode::Enter) => {
+                let sessions = &sessions_by_repo[repo_idx];
