+fn current_branch(repo_dir: &str) -> String {
+    Command::new("git")
+        .args(["branch", "--show-current"])
+        .current_dir(repo_dir)
+        .output()
+        .ok()
+        .and_then(|o| String::from_utf8(o.stdout).ok())
+        .map(|s| s.trim().to_string())
+        .filter(|s| !s.is_empty())
+        .unwrap_or_else(|| "HEAD".to_string())
+}
+
+fn agent_color(name: &str) -> Color {
+    match name {
+        "Claude Code" => Color::Indexed(214),
+        "Copilot"     => Color::Indexed(99),
+        "Cursor"      => Color::Indexed(33),
+        "Gemini"      => Color::Indexed(75),
+        "Aider"       => Color::Indexed(42),
+        "ChatGPT"     => Color::Indexed(35),
+        "Windsurf"    => Color::Indexed(44),
+        "Amazon Q"    => Color::Indexed(208),
+        _             => Color::Indexed(245),
+    }
+}
+
+fn session_action_bar(active: usize) -> Paragraph<'static> {
+    const ACTIONS: &[&str] = &["cd to session", "cd + resume"];
+    let mut spans = vec![
+        Span::styled("↑↓ navigate  Tab cycle  Enter confirm  Esc back    ", Style::default().fg(Color::Indexed(245))),
+    ];
+    for (i, &label) in ACTIONS.iter().enumerate() {
+        if i == active {
+            spans.push(Span::styled(format!(" {label} "), Style::default().fg(Color::Indexed(255)).bg(Color::Indexed(237))));
+        } else {
+            spans.push(Span::styled(format!(" {label} "), Style::default().fg(Color::Indexed(245))));
+        }
+        if i + 1 < ACTIONS.len() {
+            spans.push(Span::raw("  "));
+        }
+    }
+    Paragraph::new(Line::from(spans))
+}
+
+fn format_tokens(n: i64) -> String {
+    if n == 0 { return "-".to_string(); }
+    if n < 1_000 { return format!("{n}"); }
+    if n < 1_000_000 { return format!("{:.1}k", n as f64 / 1_000.0); }
+    format!("{:.1}M", n as f64 / 1_000_000.0)
+}
+
+fn relative_time(dt: chrono::DateTime<Utc>) -> String {
+    let secs = (Utc::now() - dt).num_seconds();
+    match secs {
+        s if s < 60 => "just now".to_string(),
+        s if s < 3_600 => format!("{} min{} ago", s / 60, if s / 60 == 1 { "" } else { "s" }),
+        s if s < 86_400 => format!("{} hr{} ago", s / 3_600, if s / 3_600 == 1 { "" } else { "s" }),
+        s if s < 604_800 => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
+        s if s < 2_592_000 => format!("{} wk{} ago", s / 604_800, if s / 604_800 == 1 { "" } else { "s" }),
+        s if s < 31_536_000 => format!("{} mo ago", s / 2_592_000),
+        s => format!("{} yr{} ago", s / 31_536_000, if s / 31_536_000 == 1 { "" } else { "s" }),
+    }
+}
+
+fn truncate(s: &str, max: usize) -> String {
+    if s.chars().count() <= max {
+        s.to_string()
+    } else {
+        format!("{}…", s.chars().take(max - 1).collect::<String>())
+    }
+}
