+                        Span::styled("  esc to go back", Style::default().fg(Color::Indexed(245))),
+                    ]);
+                    f.render_widget(Paragraph::new(title), chunks[0]);
+
+                    let sessions = &sessions_by_repo[repo_idx];
+
+                    if sessions.is_empty() {
+                        let msg = Paragraph::new("No sessions found for this repository.")
+                            .style(Style::default().fg(Color::Indexed(245)));
+                        f.render_widget(msg, chunks[1]);
+                    } else {
+                        let header = Row::new(["", "Last Prompt", "Agent", "Tokens", "Updated"])
+                            .style(Style::default().fg(Color::Indexed(245)));
+
+                        let rows: Vec<Row> = sessions.iter().enumerate().map(|(i, s)| {
+                            let age = (now - s.updated_at).num_seconds();
