+                            Constraint::Fill(1),
+                            Constraint::Length(12),
+                            Constraint::Length(8),
+                            Constraint::Length(13),
+                        ])
+                        .header(header)
+                        .row_highlight_style(Style::default().fg(Color::Indexed(255)).bg(Color::Indexed(237)))
+                        .column_spacing(2);
+
+                        f.render_stateful_widget(table, chunks[1], &mut session_state);
+                    }
+
+                    f.render_widget(session_action_bar(active_action), chunks[2]);
+                }
