+        "Gemini"      => Color::Indexed(75),
+        "Aider"       => Color::Indexed(42),
+        "ChatGPT"     => Color::Indexed(35),
+        "Windsurf"    => Color::Indexed(44),
+        "Amazon Q"    => Color::Indexed(208),
+        _             => Color::Indexed(245),
+    }
+}
