    // Fast path: connect to an already-running instance (previous CLI invocation left it running).
    if let Ok(db) = Database::connect(&url).await {
        Migrator::up(&db, None).await.context("failed to run migrations")?;
        return Ok(db);
    }

    // Slow path: download binary if needed, initialise data dir, start daemon.
    let mut settings = Settings::default();
    settings.installation_dir = gossamer_dir.join("pgbin");
    settings.data_dir = gossamer_dir.join("pgdata");
    settings.port = PG_PORT;
    settings.username = PG_USER.to_string();
    settings.password = PG_PASS.to_string();
    settings.temporary = false;

    let mut pg = PostgreSQL::new(settings);
    pg.setup().await.context("failed to set up embedded PostgreSQL")?;
    pg.start().await.context("failed to start embedded PostgreSQL")?;

    if !pg.database_exists(DB_NAME).await.context("failed to check database")? {
        pg.create_database(DB_NAME).await.context("failed to create database")?;
    }

    let db = Database::connect(&url).await.context("failed to connect to database")?;
    Migrator::up(&db, None).await.context("failed to run migrations")?;

    // Leak the handle so PostgreSQL keeps running as a daemon after the CLI exits.
    // The next invocation will take the fast path above.
    Box::leak(Box::new(pg));

    Ok(db)
}

